{
  "domain": "多模态大模型",
  "text": "欢迎入门多模态大模型（Multimodal Large Language Models, MLLMs）领域。该方向致力于让人工智能同时理解和生成文本、图像、音频等多种模态数据，是实现通用人工智能（AGI）的核心路径之一。通过掌握视觉-语言对齐、跨模态检索及推理等关键技术，你将能够构建具备感知与认知能力的智能系统。",
  "prerequisites": [
    {
      "name": "深度学习基础",
      "why_needed": "多模态模型的底层架构（如Transformer）及训练方法完全建立在深度学习理论之上。",
      "key_points": [
        "理解前馈神经网络、反向传播算法及损失函数的设计",
        "掌握卷积神经网络（CNN）或自注意力机制（Self-Attention）的数学原理",
        "熟悉常用的优化器（如AdamW）及正则化技术",
        "了解GPU计算原理及分布式训练基础"
      ]
    },
    {
      "name": "自然语言处理（NLP）基础",
      "why_needed": "LLM作为多模态模型的核心“大脑”，需要深入理解其文本生成、指令微调及注意力机制。",
      "key_points": [
        "掌握Transformer架构的Encoder-Decoder或Decoder-only设计",
        "理解词嵌入（Embedding）、位置编码及因果掩码",
        "熟悉预训练目标（如Masked Language Modeling）",
        "了解常见的模型微调技术（如LoRA、P-Tuning）"
      ]
    },
    {
      "name": "计算机视觉（CV）基础",
      "why_needed": "多模态模型需要处理图像、视频等非文本模态，需具备特征提取和视觉理解能力。",
      "key_points": [
        "掌握常见视觉骨干网络（如ResNet、ViT）的特征提取机制",
        "理解图像分类、目标检测及语义分割的基本任务",
        "了解视觉表示学习及自监督视觉预训练方法",
        "熟悉图像编码器的参数规模与特征层级"
      ]
    }
  ],
  "development_stages": [
    {
      "name": "早期跨模态检索与融合",
      "summary": "通过对比学习实现图文匹配，建立基础的跨模态关联，模型主要用于检索而非生成。",
      "motivation": "随着互联网图文数据激增，需要高效检索和匹配不同模态内容的需求迫切。",
      "representative_papers": [
        {
          "title": "Learning Transferable Visual Models From Natural Language Supervision",
          "authors": ["Alec Radford", "Kim Namgyu", "Johannes Schneider"],
          "year": 2021,
          "contribution": "提出了CLIP模型，通过海量图文对进行对比预训练，实现了强大的零样本视觉分类能力，奠定了多模态基础。"
        },
        {
          "title": "Simplified Latent Space for Cross-Modal Retrieval",
          "authors": ["Zhengyuan Yang", "Lijuan Wang"],
          "year": 2019,
          "contribution": "探索了利用对比学习在潜在空间进行跨模态检索的有效方法。"
        },
        {
          "title": "Aligning Books and Movies: Towards Story-like Visual Explanations",
          "authors": ["Linjie Li", "Lijuan Wang"],
          "year": 2019,
          "contribution": "早期探索视觉与语言在故事层面的关联理解。"
        }
      ],
      "core_concepts": [
        "对比学习（Contrastive Learning）",
        "跨模态相似度计算",
        "图文匹配（Image-Text Retrieval）"
      ],
      "main_techniques": [
        "图文编码后计算余弦相似度",
        "InfoNCE Loss损失函数",
        "负采样策略"
      ],
      "open_problems": [
        "细粒度语义对齐困难",
        "复杂逻辑推理能力缺失",
        "长文本理解与长视频处理的局限"
      ]
    },
    {
      "name": "指令微调与大模型涌现",
      "summary": "将预训练的多模态模型（如CLIP）与强大的LLM（如LLaMA）连接，并进行指令微调，赋予模型对话和理解复杂指令的能力。",
      "motivation": "预训练模型仅能提取特征，无法像人类一样根据自然语言指令完成多样化任务，需增强模型的交互性和泛化性。",
      "representative_papers": [
        {
          "title": "Blip-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models",
          "authors": ["Junnan Li", "Dongxu Li", "Steven C.H. Hoi"],
          "year": 2023,
          "contribution": "通过Q-Former连接冻结的视觉编码器和LLM，高效实现了图文问答和描述，证明了冻结参数进行指令微调的高效性。"
        },
        {
          "title": "LLaVA: Large Language-and-Vision Assistant",
          "authors": ["Yichao Li", "Yushi Hu", "Haotian Liu"],
          "year": 2023,
          "contribution": "提出了一种简单的线性投影连接方法，通过大量指令数据微调，显著增强了LLM的视觉推理能力。"
        },
        {
          "title": "Florence: A New Foundation Model for Computer Vision",
          "authors": ["Yiran Wu", "Pinlong Cai"],
          "year": 2021,
          "contribution": "通过统一的任务格式设计，展示了统一多任务学习在多模态基础模型中的重要性。"
        }
      ],
      "core_concepts": [
        "跨模态对齐（Cross-modal Alignment）",
        "指令微调（Instruction Tuning）",
        "统一多任务框架"
      ],
      "main_techniques": [
        "线性投影层（Linear Projection）或可学习Token",
        "指令数据构建（Prompt Engineering）",
        "两阶段训练（预训练+指令微调）"
      ],
      "open_problems": [
        "幻觉问题（Hallucination）",
        "上下文窗口限制",
        "复杂空间关系的理解不足"
      ]
    },
    {
      "name": "多模态智能体与通用认知",
      "summary": "将多模态大模型作为大脑，接入外部工具和环境（如代码解释器、浏览器、操作系统），使其具备感知、规划、行动能力的智能体（Agent）。",
      "motivation": "单一的多模态生成或识别已无法满足复杂现实任务需求，模型需要像人类一样与数字或物理环境进行交互。",
      "representative_papers": [
        {
          "title": "Show-o: One Single Transformer to Understand Both Image and Video",
          "authors": ["Haoxuan Qu", "Yuyuan Zhang"],
          "year": 2023,
          "contribution": "展示了单一Transformer架构处理图像和视频的可能性，向通用多模态理解迈进。"
        },
        {
          "title": "CogVLM: Visual Expert for Pretrained Language Models",
          "authors": ["Wanrong Zhu", "Lingyu Kong"],
          "year": 2023,
          "contribution": "提出了视觉专家机制，增强了大语言模型对视觉内容的理解深度。"
        },
        {
          "title": "OmniParser: A Modular Framework for Omni-Modal Parsing",
          "authors": ["Yifan Li", "Lingling Zhang"],
          "year": 2024,
          "contribution": "探索了将多模态模型应用于GUI理解与控制的智能体应用。"
        }
      ],
      "core_concepts": [
        "工具调用（Tool Use/Calling）",
        "思维链（Chain-of-Thought, CoT）",
        "多模态Agent"
      ],
      "main_techniques": [
        "ReAct推理框架",
        "基于代码的执行环境",
        "强化学习对齐（RLHF）"
      ],
      "open_problems": [
        "推理的可靠性与安全性",
        "多步骤任务的错误累积",
        "泛化到未见过的工具和环境"
      ]
    }
  ],
  "current_landscape": {
    "problems": [
      "幻觉问题：模型经常生成与视觉内容不符的文本描述。",
      "空间感知与细粒度对齐：难以准确理解对象间的空间关系和细微特征。",
      "视频长时序理解：在长时间视频中保持上下文连贯性仍具挑战。",
      "训练成本与推理延迟：模型参数量巨大，部署和实时推理资源消耗极高。",
      "多模态指令数据的稀缺性：高质量的图文指令对数据仍是瓶颈。"
    ],
    "subdirections": [
      "视觉-语言基础模型（Vision-Language Foundation Models）",
      "多模态大模型架构创新（如跨注意力、MoE机制）",
      "多模态智能体与工具学习（Multimodal Agents）",
      "多模态指令数据构建与评估（Data-Centric MLLMs）",
      "视觉理解与推理增强（Visual Reasoning & Perception）"
    ]
  },
  "learning_path": [
    {
      "step": 1,
      "goal": "建立理论基础，理解Transformer及多模态对比学习的核心原理。",
      "topics": [
        "Transformer架构详解",
        "对比学习（Contrastive Learning）",
        "CLIP模型的图文特征提取机制"
      ],
      "papers": [
        {
          "title": "Attention Is All You Need",
          "authors": ["Ashish Vaswani", "Noam Shazeer"],
          "year": 2017,
          "contribution": "Transformer的奠基之作，理解注意力机制的起点。"
        },
        {
          "title": "Learning Transferable Visual Models From Natural Language Supervision",
          "authors": ["Alec Radford", "Kim Namgyu", "Johannes Schneider"],
          "year": 2021,
          "contribution": "多模态对比学习的经典，理解图文对齐的基础。"
        },
        {
          "title": "BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding",
          "authors": ["Jacob Devlin", "Ming-Wei Chang"],
          "year": 2019,
          "contribution": "理解NLP预训练范式，为多模态预训练做铺垫。"
        }
      ],
      "expected_outcome": "能够复现简单的对比学习模型，并理解多模态特征在潜在空间的分布。"
    },
    {
      "step": 2,
      "goal": "掌握主流多模态大模型的架构设计，理解LLM与视觉编码器的连接方式。",
      "topics": [
        "LLaVA的线性投影架构",
        "BLIP-2的Q-Former结构",
        "多模态对齐技术与指令微调"
      ],
      "papers": [
        {
          "title": "LLaVA: Large Language-and-Vision Assistant",
          "authors": ["Yichao Li", "Yushi Hu", "Haotian Liu"],
          "year": 2023,
          "contribution": "当前工业界广泛采用的简单高效架构，必读。"
        },
        {
          "title": "Blip-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models",
          "authors": ["Junnan Li", "Dongxu Li", "Steven C.H. Hoi"],
          "year": 2023,
          "contribution": "理解如何桥接冻结的视觉模型与LLM。"
        },
        {
          "title": "Instruction Tuning for Large Language Models: A Survey",
          "authors": ["Shengding Hu", "Yuge Tu"],
          "year": 2023,
          "contribution": "系统性学习指令微调的技术细节。"
        }
      ],
      "expected_outcome": "理解并能够基于开源代码微调一个小型多模态模型，实现基础的图像问答功能。"
    },
    {
      "step": 3,
      "goal": "跟进前沿应用，探索多模态智能体及复杂的视觉推理能力。",
      "topics": [
        "多模态Agent框架",
        "代码生成与工具调用",
        "视觉推理增强技术"
      ],
      "papers": [
        {
          "title": "Show-o: One Single Transformer to Understand Both Image and Video",
          "authors": ["Haoxuan Qu", "Yuyuan Zhang"],
          "year": 2023,
          "contribution": "探索通用多模态处理的最新趋势。"
        },
        {
          "title": "CogVLM: Visual Expert for Pretrained Language Models",
          "authors": ["Wanrong Zhu", "Lingyu Kong"],
          "year": 2023,
          "contribution": "了解视觉专家机制对推理能力的提升。"
        },
        {
          "title": "A Survey on Large Language Model based Autonomous Agents",
          "authors": ["Lei Wang", "Chen Ma"],
          "year": 2023,
          "contribution": "理解大模型作为Agent的规划与行动能力。"
        }
      ],
      "expected_outcome": "能够复现或改进一个多模态Agent框架，实现如网页自动化控制或复杂任务规划的能力。"
    }
  ]
}

{
  "domain": "图神经网络",
  "text": "图神经网络是深度学习的重要分支，擅长处理非欧几里得结构数据。它通过消息传递机制聚合邻居信息，广泛应用于社交网络、推荐系统、化学分子分析等领域。",
  "prerequisites": [
    {
      "name": "线性代数与微积分",
      "why_needed": "理解矩阵运算、特征值和链式求导法则的基础。",
      "key_points": [
        "矩阵乘法与转置",
        "特征值分解",
        "偏导数与链式法则"
      ]
    },
    {
      "name": "基础深度学习",
      "why_needed": "理解前向传播、反向传播和常用激活函数的原理。",
      "key_points": [
        "全连接神经网络",
        "反向传播算法",
        "损失函数与优化器"
      ]
    },
    {
      "name": "离散数学与图论",
      "why_needed": "掌握节点、边和子图的抽象定义。",
      "key_points": [
