      "representative_papers": [
        {
          "title": "Semi-Supervised Classification with Graph Convolutional Networks",
          "authors": [
            "Thomas N. Kipf",
            "Max Welling"
          ],
          "year": 2017,
          "contribution": "提出了GCN，使用一阶近似简化了谱卷积计算，成为领域奠基之作。"
        }
      ],
      "core_concepts": [
        "图注意力机制",
        "消息传递网络",
        "节点表征学习"
      ],
      "main_techniques": [
        "邻接矩阵归一化",
        "多层感知机与非线性激活"
      ],
      "open_problems": [
        "过平滑现象",
        "计算可扩展性"
      ]
    },
    {
