      "representative_papers": [
        {
          "title": "GraphSAGE: Inductive Representation Learning on Large Graphs",
          "authors": [
            "William L. Hamilton",
            "Zhitao Ying",
            "Jure Leskovec"
          ],
          "year": 2017,
          "contribution": "提出了GraphSAGE，支持归纳式学习和大规模图训练。"
