{
  "domain": "联邦学习",
  "text": "联邦学习是一种机器学习范式，允许多个参与方在不交换原始数据的情况下协同训练模型。它解决了数据孤岛问题，特别适用于隐私敏感和合规要求严格的领域。该方向结合了分布式系统优化、密码学和机器学习，是当前人工智能安全与隐私保护领域的核心热点之一。",
  "prerequisites": [
    {
      "name": "深度学习基础",
      "why_needed": "联邦学习的本质是分布式深度学习，不掌握神经网络训练原理无法理解模型更新机制。",
      "key_points": [
        "前向传播与反向传播算法",
        "损失函数与梯度下降优化器",
        "常见模型架构（CNN, RNN, Transformer）"
      ]
    },
    {
      "name": "分布式计算原理",
      "why_needed": "联邦学习涉及多台设备协同训练，需理解并行计算、网络通信与系统瓶颈。",
      "key_points": [
        "模型并行与数据并行概念",
        "网络延迟、带宽与通信开销",
        "服务器-客户端架构模式"
      ]
    },
    {
      "name": "密码学与隐私保护",
      "why_needed": "联邦学习的安全性保障（如隐私泄露防范）依赖于密码学技术。",
